20	import {
21	    Dictionary, TooltipRenderMode, ColorString,
22	    TooltipOrderMode, DimensionType, CommonTooltipOption, OptionDataValue
23	} from '../../util/types';
24	import {
25	    TooltipMarkerType, getTooltipMarker, encodeHTML,
26	    makeValueReadable, convertToColorString
27	} from '../../util/format';
28	import { isString, each, hasOwn, isArray, map, assert, extend } from 'zrender/src/core/util';
29	import { SortOrderComparator } from '../../data/helper/dataValueHelper';
