470	export function retrieveVisualColorForTooltipMarker(
471	    series: SeriesModel,
472	    dataIndex: number
473	): ColorString {
474	    const style = series.getData().getItemVisual(dataIndex, 'style');
475	    const color = style[series.visualDrawType];
476	    return convertToColorString(color);
477	}
478	
479	export function getPaddingFromTooltipModel(
480	    model: Model<TooltipOption>,
481	    renderMode: TooltipRenderMode
482	): number | number[] {
483	    const padding = model.get('padding');
484	    return padding != null
485	        ? padding
486	        // We give slightly different to look pretty.
487	        : renderMode === 'richText'
488	        ? [8, 10]
489	        : 10;
490	}
