504	    private _showOrMove(
505	        tooltipModel: Model<TooltipOption>,
506	        cb: () => void
507	    ) {
508	        // showDelay is used in this case: tooltip.enterable is set
509	        // as true. User intent to move mouse into tooltip and click
510	        // something. `showDelay` makes it easier to enter the content
511	        // but tooltip do not move immediately.
512	        const delay = tooltipModel.get('showDelay');
513	        cb = bind(cb, this);
514	        clearTimeout(this._showTimout);
515	        delay > 0
516	            ? (this._showTimout = setTimeout(cb, delay) as any)
517	            : cb();
518	    }
