520	    private _showAxisTooltip(
521	        dataByCoordSys: DataByCoordSys[],
522	        e: TryShowParams
523	    ) {
524	        const ecModel = this._ecModel;
525	        const globalTooltipModel = this._tooltipModel;
526	        const point = [e.offsetX, e.offsetY];
527	        const singleTooltipModel = buildTooltipModel(
528	            [e.tooltipOption],
529	            globalTooltipModel
530	        );
531	        const renderMode = this._renderMode;
532	        const cbParamsList: TooltipCallbackDataParams[] = [];
533	        const articleMarkup = createTooltipMarkup('section', {
534	            blocks: [],
535	            noHeader: true
536	        });
537	        // Only for legacy: `Serise['formatTooltip']` returns a string.
538	        const markupTextArrLegacy: string[] = [];
539	        const markupStyleCreator = new TooltipMarkupStyleCreator();
540	
541	        each(dataByCoordSys, function (itemCoordSys) {
542	            each(itemCoordSys.dataByAxis, function (axisItem) {
