/**
 * Find the tooltip content DOM created by `TooltipHTMLContent`.
 */
function getTooltipEl(chart: EChartsType): HTMLElement {
    const children = chart.getDom().children;
    for (let i = 0; i < children.length; i++) {
        const child = children[i] as HTMLElement;
        if ((child as any).domBelongToZr) {
            return child;
        }
    }
    return null;
}

describe('component/tooltip', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    describe('legend name XSS', function () {

        const XSS_NAME = '<img src="x" onerror="window.__ec_xss_flag__ = true" />';

        function createLegendTooltipChart(name: string) {
            chart.setOption({
                tooltip: {},
                legend: {
                    tooltip: {
                        show: true
                    }
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    name: name,
                    data: [1, 2]
                }]
            });
            chart.dispatchAction({
                type: 'showTip',
                legendIndex: 0,
                name: name
            });
        }

        it('should escape html in legend name', function () {
            createLegendTooltipChart(XSS_NAME);

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl).not.toBeNull();

            const html = tooltipEl.innerHTML;
            // The html string should be escaped rather than being live markup.
            expect(html.indexOf('&lt;img') >= 0).toBe(true);
            expect(html.indexOf('<img') < 0).toBe(true);
            expect(tooltipEl.querySelector('img')).toBeNull();
            // It's displayed as plain text.
            expect(tooltipEl.textContent.indexOf(XSS_NAME) >= 0).toBe(true);
        });

        it('should not encode the name repeatedly', function () {
            createLegendTooltipChart(XSS_NAME);
            // Show the tooltip of the same legend item again.
            chart.dispatchAction({
                type: 'showTip',
                legendIndex: 0,
                name: XSS_NAME
            });

            const html = getTooltipEl(chart).innerHTML;
            expect(html.indexOf('&amp;lt;') < 0).toBe(true);
            expect(getTooltipEl(chart).textContent.indexOf(XSS_NAME) >= 0).toBe(true);
        });

        it('should keep normal legend name working', function () {
            createLegendTooltipChart('Sales');

            const tooltipEl = getTooltipEl(chart);
            expect(tooltipEl.innerHTML.indexOf('Sales') >= 0).toBe(true);
            expect(tooltipEl.textContent.indexOf('Sales') >= 0).toBe(true);
        });

        it('should not break richText render mode', function () {
            expect(function () {
                chart.setOption({
                    tooltip: {
                        renderMode: 'richText'
                    },
                    legend: {
                        tooltip: {
                            show: true
                        }
                    },
                    xAxis: {
                        type: 'category',
                        data: ['A', 'B']
                    },
                    yAxis: {},
                    series: [{
                        type: 'bar',
                        name: XSS_NAME,
                        data: [1, 2]
                    }]
                }, true);
                chart.dispatchAction({
                    type: 'showTip',
                    legendIndex: 0,
                    name: XSS_NAME
                });
            }).not.toThrow();
        });
    });
});

