const TOOLTIP_LINE_HEIGHT_CSS = 'line-height:1';

/**
 * `textStyle.lineHeight` should be respected by the default tooltip content,
 * otherwise the hard coded `line-height: 1` makes it useless. (#20395)
 */
function getTooltipLineHeightCss(textStyle: TooltipOption['textStyle']): string {
    const lineHeight = textStyle && textStyle.lineHeight;
    return lineHeight != null
        // `textStyle` is probably from user input, should be encoded to reduce security risk.
        ? `line-height:${encodeHTML(lineHeight + '')}px`
        : TOOLTIP_LINE_HEIGHT_CSS;
}

