import { EChartsType } from '../../../../../src/echarts';
import { createChart } from '../../../core/utHelper';

describe('scratch/notMerge', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeOption(extraTooltip?: any) {
        return {
            tooltip: Object.assign({}, extraTooltip),
            xAxis: {
                type: 'category',
                data: ['A', 'B']
            },
            yAxis: {},
            series: [{
                type: 'line',
                name: 'S1',
                data: [11, 22]
            }]
        };
    }

    it('scenario A: notMerge twice then showTip', function () {
        chart.setOption(makeOption(), true);
        chart.setOption(makeOption(), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        console.log('A ok');
    });

    it('scenario B: showTip between notMerge, with timers flushed', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption({ alwaysShowContent: true }), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        jest.runOnlyPendingTimers();
        chart.setOption(makeOption({ alwaysShowContent: true }), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        jest.runOnlyPendingTimers();
        console.log('B ok');
        jest.useRealTimers();
    });

    it('scenario C: tooltip removed by notMerge, then timers flushed', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption(), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        const optionNoTooltip: any = makeOption();
        delete optionNoTooltip.tooltip;
        chart.setOption(optionNoTooltip, true);
        jest.runOnlyPendingTimers();
        console.log('C ok');
        jest.useRealTimers();
    });

    it('scenario D: notMerge with different series, keep show', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption(), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        chart.setOption({
            tooltip: {},
            xAxis: { type: 'category', data: ['C'] },
            yAxis: {},
            series: []
        }, true);
        jest.runOnlyPendingTimers();
        console.log('D ok');
        jest.useRealTimers();
    });

    it('scenario E: axis trigger, notMerge, keep show', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption({ trigger: 'axis' }), true);
        chart.getZr().handler.dispatch('mousemove', {
            zrX: 100,
            zrY: 100,
            offsetX: 100,
            offsetY: 100
        } as any);
        jest.runOnlyPendingTimers();
        chart.setOption(makeOption({ trigger: 'axis' }), true);
        jest.runOnlyPendingTimers();
        console.log('E ok');
        jest.useRealTimers();
    });
});

