import TooltipHTMLContent from '../../../../../src/component/tooltip/TooltipHTMLContent';

const hits: string[] = [];

['update', 'show', 'setContent', 'getSize', 'moveTo', '_moveIfResized', 'hide', 'hideLater'].forEach(name => {
    const orig = (TooltipHTMLContent.prototype as any)[name];
    (TooltipHTMLContent.prototype as any)[name] = function (this: any, ...args: any[]) {
        if (!this.el) {
            hits.push(name);
            console.log('POST_DISPOSE_CALL: ' + name + '\n' + new Error().stack);
        }
        return orig.apply(this, args);
    };
});

describe('scratch/notMerge', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
        hits.length = 0;
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeOption(extraTooltip?: any, trigger?: string) {
        return {
            tooltip: Object.assign({ trigger: trigger || 'item' }, extraTooltip),
            xAxis: {
                type: 'category',
                data: ['A', 'B']
            },
            yAxis: {},
            series: [{
                type: 'bar',
                name: 'S1',
                data: [11, 22]
            }]
        };
    }

    function mousemove(x: number, y: number) {
        chart.getZr().handler.dispatch('mousemove', {
            zrX: x, zrY: y, offsetX: x, offsetY: y, target: null
        } as any);
    }

    it('scenario 1: mousemove, notMerge, flush', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption(), true);
        mousemove(100, 300);
        mousemove(110, 300);
        chart.setOption(makeOption(), true);
        jest.runOnlyPendingTimers();
        mousemove(120, 300);
        jest.runOnlyPendingTimers();
        jest.useRealTimers();
        console.log('S1 hits=' + hits.join(','));
    });

    it('scenario 2: showTip, merge setOption, notMerge, flush', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption(), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        // merge update, re-render the same view -> _keepShow schedules a timeout
        chart.setOption({ series: [{ type: 'bar', data: [11, 22] }] });
        chart.setOption(makeOption(), true);
        jest.runOnlyPendingTimers();
        jest.useRealTimers();
        console.log('S2 hits=' + hits.join(','));
    });

    it('scenario 3: alwaysShowContent axis trigger', function () {
        jest.useFakeTimers();
        chart.setOption(makeOption({ alwaysShowContent: true }, 'axis'), true);
        chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: 0 });
        chart.setOption(makeOption({ alwaysShowContent: true }, 'axis'), true);
        jest.runOnlyPendingTimers();
        chart.resize({ width: 300, height: 200 });
        jest.runOnlyPendingTimers();
        jest.useRealTimers();
        console.log('S3 hits=' + hits.join(','));
    });

    it('scenario 4: notMerge twice then showTip', function () {
        chart.setOption(makeOption(), true);
        chart.setOption(makeOption(), true);
